import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.CQdiwDJy.js";const u=JSON.parse('{"title":"技能（Skills）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/skills.md","filePath":"guide/skills.md","lastUpdated":1788601681000}'),l={name:"guide/skills.md"};function o(i,t,r,n,c,h){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="技能-skills" tabindex="-1">技能（Skills） <a class="header-anchor" href="#技能-skills" aria-label="Permalink to &quot;技能（Skills）&quot;">​</a></h1><p>技能是 Tau 的轻量扩展机制：一个技能就是一个 <code>SKILL.md</code> 文件（外加可选的文档），向 AI 的提示里注入结构化描述与<strong>声明式命令</strong>——无需写任何 TypeScript 代码。</p><h2 id="三种作用域" tabindex="-1">三种作用域 <a class="header-anchor" href="#三种作用域" aria-label="Permalink to &quot;三种作用域&quot;">​</a></h2><table tabindex="0"><thead><tr><th>作用域</th><th>位置</th><th>来源</th></tr></thead><tbody><tr><td>bundled</td><td>包内 <code>packages/skills/bundled/</code></td><td>随 CLI 发布</td></tr><tr><td>user</td><td><code>$TAU_HOME/skills/&lt;name&gt;/</code>（默认 <code>~/.tau/skills/</code>）</td><td>你手动安装</td></tr><tr><td>workspace</td><td>项目里 <code>./skills/</code> 或 <code>./.tau/skills/</code></td><td>跟随你的仓库</td></tr></tbody></table><p><code>tau skill list</code> 会列出全部作用域的技能；<code>tau skill new &lt;name&gt; &quot;&lt;描述&gt;&quot;</code> 用官方模板生成骨架。</p><h2 id="一个技能长什么样" tabindex="-1">一个技能长什么样 <a class="header-anchor" href="#一个技能长什么样" aria-label="Permalink to &quot;一个技能长什么样&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-skill/</span></span>
<span class="line"><span>  SKILL.md      # frontmatter（name/description/risk）+ 命令定义 + 注入说明</span></span></code></pre></div><p>技能里的命令是<strong>声明式</strong>的：定义&quot;这个命令展开成什么意图/工具调用&quot;，而不是可执行脚本。风险声明（low/medium/high）走与内置工具相同的审查门——medium+ 命令同样要过确认，技能不能绕过安全模型。</p><h2 id="与插件-mcp-的边界" tabindex="-1">与插件（MCP）的边界 <a class="header-anchor" href="#与插件-mcp-的边界" aria-label="Permalink to &quot;与插件（MCP）的边界&quot;">​</a></h2><p>需要声明式命令、提示注入、零代码 → <strong>技能</strong>。需要真正的外部工具服务器（独立进程、自定义协议实现）→ <a href="/Tau/guide/plugins.html">插件</a>。技能是文档级扩展，插件是进程级扩展。</p><h2 id="为仓库写技能" tabindex="-1">为仓库写技能 <a class="header-anchor" href="#为仓库写技能" aria-label="Permalink to &quot;为仓库写技能&quot;">​</a></h2><p>想给 Tau 本身的开发流程写技能（或了解 SKILL.md 在本仓库里的三层模型），见<a href="/Tau/reference/skill-authoring.html">编写技能</a>。</p>`,12)])])}const m=a(l,[["render",o]]);export{u as __pageData,m as default};
